// RunLedgerSuite applies the checks of Ledger, and the checks that opts
// add, to a fresh subject of newSubject for each check.
func RunLedgerSuite[T ledger.Ledger](t *testing.T, newSubject func() T, opts ...LedgerOption) {
	t.Helper()
	RunLedgerSuiteFromHandle(t, func(*LedgerHandle) T { return newSubject() }, opts...)
}

// RunLedgerSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunLedgerSuiteFromHandle[T ledger.Ledger](t *testing.T, newSubject func(h *LedgerHandle) T, opts ...LedgerOption) {
	t.Helper()
	conform.Run(t, LedgerSuite(), ledgerSubjects(newSubject), opts...)
}

// FuzzLedgerSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzLedgerSuite[T ledger.Ledger](
	f *testing.F,
	callable conform.Callable[ledger.Ledger],
	newSubject func(h *LedgerHandle) T,
	opts ...LedgerOption,
) {
	f.Helper()
	conform.Fuzz(f, LedgerSuite(), callable, ledgerSubjects(newSubject), opts...)
}

// RunLedgerBudgets applies the allocation ceilings of Ledger and its
// checks that count allocations, and the ceilings and the checks that opts
// add, to a fresh subject of newSubject for each case.
func RunLedgerBudgets[T ledger.Ledger](t *testing.T, newSubject func(h *LedgerHandle) T, opts ...LedgerOption) {
	t.Helper()
	conform.RunBudgets(t, LedgerSuite(), ledgerSubjects(newSubject), opts...)
}

// BenchLedgerSuite measures callable on a subject of newSubject, under the
// ceilings of its budget.
func BenchLedgerSuite[T ledger.Ledger](
	b conform.B,
	callable conform.Callable[ledger.Ledger],
	newSubject func(h *LedgerHandle) T,
	opts ...LedgerOption,
) {
	b.Helper()
	conform.Bench(b, LedgerSuite(), callable, ledgerSubjects(newSubject), opts...)
}

// ledgerSubjects returns the factory of the subjects of Ledger that calls
// newSubject with the handle of each check.
func ledgerSubjects[T ledger.Ledger](newSubject func(h *LedgerHandle) T) func(h *LedgerHandle) ledger.Ledger {
	return func(h *LedgerHandle) ledger.Ledger { return newSubject(h) }
}

// ledgerRunCalls generates the calls of Ledger.Run with the inputs that
// each case draws.
var ledgerRunCalls = prop.Composite(func(c *prop.Case) func(context.Context, ledger.Ledger) error {
	bodyResults := c.Draw(prop.List(prop.SampledFrom[error](nil, conform.ErrGenerated)), "body")
	var bodyAt atomic.Int64
	body := func(context.Context) (r0 error) {
		i := int(bodyAt.Add(1) - 1)
		if i >= len(bodyResults) {
			r0 = conform.ErrGenerated
			return r0
		}
		return bodyResults[i]
	}
	return func(ctx context.Context, subject ledger.Ledger) error {
		return subject.Run(ctx, body)
	}
})

// ledgerPutCalls generates the calls of Ledger.Put with the inputs that
// each case draws.
var ledgerPutCalls = prop.Composite(func(c *prop.Case) func(context.Context, ledger.Ledger) error {
	key := c.Draw(prop.Of[string](), "key")
	value := c.Draw(prop.Of[string](), "value")
	return func(ctx context.Context, subject ledger.Ledger) error {
		return subject.Put(ctx, key, value)
	}
})

// ledgerGetCalls generates the calls of Ledger.Get with the inputs that
// each case draws.
var ledgerGetCalls = prop.Composite(func(c *prop.Case) func(context.Context, ledger.Ledger) error {
	key := c.Draw(prop.Of[string](), "key")
	return func(ctx context.Context, subject ledger.Ledger) error {
		_, err := subject.Get(ctx, key)
		return err
	}
})

// ledgerOverEmbedded is ledger.Ledger under the name of the field that
// ledgerOver embeds.
type ledgerOverEmbedded = ledger.Ledger

// ledgerOver is a subject of Ledger whose callables call spend and return
// their zero results. The planted defect of a ceiling passes a spend that
// exceeds the ceiling.
type ledgerOver struct {
	ledgerOverEmbedded
	spend func()
}

// Run calls spend and returns its zero results.
func (o ledgerOver) Run(context.Context, func(ctx context.Context) error) (r0 error) {
	o.spend()
	return r0
}

// Put calls spend and returns its zero results.
func (o ledgerOver) Put(context.Context, string, string) (r0 error) {
	o.spend()
	return r0
}

// Get calls spend and returns its zero results.
func (o ledgerOver) Get(context.Context, string) (r0 string, r1 error) {
	o.spend()
	return r0, r1
}

// newLedgerOver returns the planted defect of a ceiling of Ledger, whose
// callables call spend.
func newLedgerOver(_ *LedgerHandle, spend func()) ledger.Ledger {
	return ledgerOver{spend: spend}
}

